#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe ftp-check-an-app-cleaned-up. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/work site/leaky
printf '%s\n' 'scratch' > scratch.txt
printf '%s\n' 'kept' > site/work/keep.txt
printf '%s\n' 'kept' > site/leaky/keep.txt
cat > app.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# app.sh FOLDER-URL [leak]: the app under test. It uploads two temporary files to the folder URL (ending in /),
# then deletes both, or only the first when given leak. A failed upload or delete is curl's exit code.
url=$1
curl -sS -T scratch.txt "${url}a.tmp" -T scratch.txt "${url}b.tmp" || exit
if [ "$2" = leak ]; then
  curl -sS -o /dev/null -l -Q "-DELE a.tmp" "$url"
else
  curl -sS -o /dev/null -l -Q "-DELE a.tmp" -Q "-DELE b.tmp" "$url"
fi
EOF
cat > check.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# check.sh FOLDER-URL: lists the folder and fails, exit 1, naming what it finds if any .tmp file is left.
# A listing that fails is curl's exit code, so a folder that cannot be listed never passes.
names=$(curl -sS -l "$1") || exit
left=$(echo "$names" | tr -d '\r' | grep '\.tmp$' | tr '\n' ' ')
if [ -n "$left" ]; then echo "leftover: ${left% }"; exit 1; fi
echo clean
EOF
surl --allow-anonymous --allow-uploads --list-directories --directory site ftp://127.0.0.1:8080/ &
sleep 1
sh app.sh ftp://127.0.0.1:8080/work/ && sh check.sh ftp://127.0.0.1:8080/work/
kill $(jobs -p)
